create role anon;create role authenticated;create schema auth;create schema extensions;create table auth.users(id uuid primary key);create function auth.uid() returns uuid language sql stable as $$ select (nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;create function extensions.digest(text,text) returns bytea language sql immutable as $$ select sha256(convert_to($1,'UTF8')) $$;
create table public.system_admins(user_id uuid not null, role text default 'master_admin'::text not null, active boolean default true not null, created_by uuid, created_at timestamp with time zone default now() not null);
create table public.regente10_projects(id text not null, label text not null, status text not null, scope text default 'project'::text not null, created_at timestamp with time zone default now() not null);
create table public.regente10_missions(id uuid default gen_random_uuid() not null, owner_id uuid not null, project text not null, title text not null, original_request text not null, prompt_affinado text, diagnostic jsonb default '{}'::jsonb not null, result_plan jsonb default '[]'::jsonb not null, status text default 'afinamento'::text not null, envelope_approved_at timestamp with time zone, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null, paused boolean default false not null, budget_policy text default 'legacy'::text not null);
create table public.regente10_resources(alias text not null, resource_kind text not null, parent_alias text, owner_kind text not null, owner_project text, share_category text not null, data_class text not null, shared_projects text[] default '{}'::text[] not null, allowed_operations text[] default '{}'::text[] not null, lifecycle text default 'proposed'::text not null, policy_version integer default 1 not null, description text, policy_decision_ref text);
create table public.regente10_controls(owner_id uuid not null, emergency_stop boolean default false not null, updated_at timestamp with time zone default now() not null);
create table public.regente10_mission_budgets(mission_id uuid not null, owner_id uuid not null, currency text default 'BRL'::text not null, fx_brl_per_usd numeric(10,4) not null, fx_source text default 'maestro_budget_assumption'::text not null, fx_verified boolean default false not null, model text default 'gpt-4.1-mini'::text not null, model_price_source text default 'https://developers.openai.com/api/docs/models/gpt-4.1-mini'::text not null, model_price_date date default '2026-10-12'::date not null, estimated_text_brl numeric(14,4) not null, estimated_other_brl numeric(14,4) not null, estimated_total_brl numeric(14,4) not null, margin_pct numeric(7,2) not null, cap_brl numeric(14,4) not null, reserved_brl numeric(14,4) default 0 not null, metered_brl numeric(14,4) default 0 not null, state text default 'draft'::text not null, approved_at timestamp with time zone, approved_by uuid, created_at timestamp with time zone default now() not null, updated_at timestamp with time zone default now() not null);
alter table public.system_admins add PRIMARY KEY (user_id);
alter table public.regente10_projects add PRIMARY KEY (id);
alter table public.regente10_missions add PRIMARY KEY (id);
alter table public.regente10_resources add PRIMARY KEY (alias);
alter table public.regente10_controls add PRIMARY KEY (owner_id);
alter table public.regente10_mission_budgets add PRIMARY KEY (mission_id);
alter table public.system_admins add FOREIGN KEY (created_by) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table public.system_admins add CHECK ((role = 'master_admin'::text));
alter table public.system_admins add FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.regente10_projects add CHECK ((id ~ '^[a-z][a-z0-9-]{2,60}$'::text));
alter table public.regente10_projects add CHECK ((scope = ANY (ARRAY['project'::text, 'governance'::text])));
alter table public.regente10_projects add CHECK ((status = ANY (ARRAY['proposed'::text, 'active'::text, 'suspended'::text, 'closed'::text])));
alter table public.regente10_missions add CHECK ((budget_policy = ANY (ARRAY['legacy'::text, 'budget_v1'::text])));
alter table public.regente10_missions add CHECK (((char_length(original_request) >= 1) AND (char_length(original_request) <= 4000)));
alter table public.regente10_missions add FOREIGN KEY (owner_id) REFERENCES auth.users(id);
alter table public.regente10_missions add FOREIGN KEY (project) REFERENCES regente10_projects(id) ON UPDATE RESTRICT ON DELETE RESTRICT;
alter table public.regente10_missions add CHECK ((status = ANY (ARRAY['afinamento'::text, 'aguardando_autorizacao'::text, 'em_execucao'::text, 'em_resultados'::text, 'concluida'::text])));
alter table public.regente10_missions add CHECK (((char_length(title) >= 1) AND (char_length(title) <= 120)));
alter table public.regente10_resources add CHECK ((((owner_kind = 'project'::text) AND (owner_project IS NOT NULL)) OR ((owner_kind <> 'project'::text) AND (owner_project IS NULL))));
alter table public.regente10_resources add CHECK (((length(alias) >= 3) AND (length(alias) <= 90)));
alter table public.regente10_resources add CHECK ((data_class = ANY (ARRAY['public'::text, 'internal'::text, 'personal'::text, 'sensitive'::text, 'secret'::text])));
alter table public.regente10_resources add CHECK (((policy_decision_ref IS NULL) OR (length(policy_decision_ref) <= 90)));
alter table public.regente10_resources add CHECK ((lifecycle = ANY (ARRAY['active'::text, 'proposed'::text, 'suspended'::text])));
alter table public.regente10_resources add CHECK ((owner_kind = ANY (ARRAY['institute'::text, 'project'::text, 'person'::text])));
alter table public.regente10_resources add FOREIGN KEY (owner_project) REFERENCES regente10_projects(id);
alter table public.regente10_resources add FOREIGN KEY (parent_alias) REFERENCES regente10_resources(alias);
alter table public.regente10_resources add CHECK ((policy_version >= 1));
alter table public.regente10_resources add CHECK ((resource_kind = ANY (ARRAY['account'::text, 'container'::text, 'item'::text, 'service'::text, 'runtime'::text])));
alter table public.regente10_resources add CHECK ((share_category = ANY (ARRAY['institutional_common'::text, 'exclusive'::text, 'shared'::text, 'restricted'::text])));
alter table public.regente10_controls add FOREIGN KEY (owner_id) REFERENCES auth.users(id);
alter table public.regente10_mission_budgets add FOREIGN KEY (approved_by) REFERENCES auth.users(id);
alter table public.regente10_mission_budgets add CHECK (((cap_brl >= estimated_total_brl) AND (cap_brl <= (100000)::numeric)));
alter table public.regente10_mission_budgets add CHECK ((((state = 'draft'::text) AND (approved_at IS NULL) AND (approved_by IS NULL)) OR ((state = 'approved'::text) AND (approved_at IS NOT NULL) AND (approved_by = owner_id))));
alter table public.regente10_mission_budgets add CHECK (((reserved_brl + metered_brl) <= cap_brl));
alter table public.regente10_mission_budgets add CHECK ((currency = 'BRL'::text));
alter table public.regente10_mission_budgets add CHECK ((estimated_other_brl >= (0)::numeric));
alter table public.regente10_mission_budgets add CHECK ((estimated_text_brl >= (0)::numeric));
alter table public.regente10_mission_budgets add CHECK ((estimated_total_brl >= (0)::numeric));
alter table public.regente10_mission_budgets add CHECK (((fx_brl_per_usd >= (1)::numeric) AND (fx_brl_per_usd <= (20)::numeric)));
alter table public.regente10_mission_budgets add CHECK ((fx_source = 'maestro_budget_assumption'::text));
alter table public.regente10_mission_budgets add CHECK ((fx_verified = false));
alter table public.regente10_mission_budgets add CHECK (((margin_pct >= (0)::numeric) AND (margin_pct <= (300)::numeric)));
alter table public.regente10_mission_budgets add CHECK ((metered_brl >= (0)::numeric));
alter table public.regente10_mission_budgets add FOREIGN KEY (mission_id) REFERENCES regente10_missions(id) ON DELETE CASCADE;
alter table public.regente10_mission_budgets add CHECK ((model = 'gpt-4.1-mini'::text));
alter table public.regente10_mission_budgets add FOREIGN KEY (owner_id) REFERENCES auth.users(id);
alter table public.regente10_mission_budgets add CHECK ((reserved_brl >= (0)::numeric));
alter table public.regente10_mission_budgets add CHECK ((state = ANY (ARRAY['draft'::text, 'approved'::text])));
